#include <iostream>
#include <queue>
#include <vector>

int main() {
  auto cmp = [](int a, int b) { return a % 10 > b % 10; };
  std::priority_queue<int, std::vector<int>, decltype(cmp)> pq(cmp);
  for (int x : {15, 21, 7, 32}) pq.push(x);
  while (!pq.empty()) {
    std::cout << pq.top() << ' ';
    pq.pop();
  }
  std::cout << '\n';
}

#include <iostream>
#include <queue>
#include <string>
#include <utility>

int main() {
  std::priority_queue<std::string> pq;
  pq.push(std::string(30, 'x'));
  std::string s = std::move(pq.top());
  std::cout << s.size() << ' ' << pq.top().size() << '\n';
}

